const listTransactions = `-- name: ListTransactions :many
select
  t.id, t.account_id, t.external_id, t.tx_date, t.tx_amount_cents, t.tx_currency, t.tx_direction, t.tx_desc, t.balance_after_cents, t.balance_currency, t.merchant, t.category_id, t.category_manually_set, t.merchant_manually_set, t.suggestions, t.user_notes, t.foreign_amount_cents, t.foreign_currency, t.exchange_rate, t.created_at, t.updated_at, t.split_from_id, t.forgiven, t.source,
  COALESCE((SELECT r.id FROM receipts r WHERE r.transaction_id = t.id LIMIT 1), 0)::bigint as receipt_id
from
  transactions t
  join accounts a on t.account_id = a.id
  left join account_users au on a.id = au.account_id
  and au.user_id = $1::uuid
  left join categories c on t.category_id = c.id
where
  (
    a.owner_id = $1::uuid
    or au.user_id is not null
  )
  and (
    $2::timestamptz is null
    or $3::bigint is null
    or (t.tx_date, t.id) < (
      $2::timestamptz,
      $3::bigint
    )
  )
  and (
    $4::timestamptz is null
    or t.tx_date >= $4::timestamptz
  )
  and (
    $5::timestamptz is null
    or t.tx_date <= $5::timestamptz
  )
  and (
    $6::bigint is null
    or t.tx_amount_cents >= $6::bigint
  )
  and (
    $7::bigint is null
    or t.tx_amount_cents <= $7::bigint
  )
  and (
    $8::smallint is null
    or t.tx_direction = $8::smallint
  )
  and (
    $9::bigint [] is null
    or t.account_id = ANY($9::bigint [])
  )
  and (
    $10::text [] is null
    or c.slug = ANY($10::text [])
  )
  and (
    $11::text is null
    or t.merchant ILIKE ('%' || $11::text || '%')
  )
  and (
    $12::text is null
    or t.tx_desc ILIKE ('%' || $12::text || '%')
  )
  and (
    $13::char(3) is null
    or t.tx_currency = $13::char(3)
  )
  and (
    $14::time is null
    or t.tx_date::time >= $14::time
  )
  and (
    $15::time is null
    or t.tx_date::time <= $15::time
  )
  and (
    $16::boolean is null
    or (
      $16::boolean = true
      and t.category_id is null
    )
  )
order by
  t.tx_date desc,
  t.id desc
limit
  COALESCE($17::int, 100)
`

