const updateTransaction = `-- name: UpdateTransaction :exec
update
  transactions
set
  external_id = coalesce($1::text, external_id),
  account_id = coalesce($2::bigint, account_id),
  tx_date = coalesce($3::timestamptz, tx_date),
  tx_amount_cents = coalesce($4::bigint, tx_amount_cents),
  tx_currency = coalesce($5::char(3), tx_currency),
  tx_direction = coalesce($6::smallint, tx_direction),
  tx_desc = coalesce($7::text, tx_desc),
  category_id = case when $8::boolean then null else coalesce($9::bigint, category_id) end,
  merchant = coalesce($10::text, merchant),
  user_notes = coalesce($11::text, user_notes),
  foreign_amount_cents = coalesce($12::bigint, foreign_amount_cents),
  foreign_currency = coalesce($13::char(3), foreign_currency),
  exchange_rate = coalesce($14::double precision, exchange_rate),
  suggestions = coalesce($15::text[], suggestions),
  category_manually_set = coalesce($16::boolean, category_manually_set),
  merchant_manually_set = coalesce($17::boolean, merchant_manually_set),
  forgiven = coalesce($18::boolean, forgiven)
where
  id = $19::bigint
  and account_id in (
    select
      a.id
    from
      accounts a
      left join account_users au on a.id = au.account_id
      and au.user_id = $20::uuid
    where
      a.owner_id = $20::uuid
      or au.user_id is not null
  )
`

type UpdateTransactionParams struct {
	ExternalID          *string    `db:"external_id" json:"external_id"`
	AccountID           *int64     `db:"account_id" json:"account_id"`
	TxDate              *time.Time `db:"tx_date" json:"tx_date"`
	TxAmountCents       *int64     `db:"tx_amount_cents" json:"tx_amount_cents"`
	TxCurrency          *string    `db:"tx_currency" json:"tx_currency"`
	TxDirection         *int16     `db:"tx_direction" json:"tx_direction"`
	TxDesc              *string    `db:"tx_desc" json:"tx_desc"`
	ClearCategory       bool       `db:"clear_category" json:"clear_category"`
	CategoryID          *int64     `db:"category_id" json:"category_id"`
	Merchant            *string    `db:"merchant" json:"merchant"`
	UserNotes           *string    `db:"user_notes" json:"user_notes"`
	ForeignAmountCents  *int64     `db:"foreign_amount_cents" json:"foreign_amount_cents"`
	ForeignCurrency     *string    `db:"foreign_currency" json:"foreign_currency"`
	ExchangeRate        *float64   `db:"exchange_rate" json:"exchange_rate"`
	Suggestions         []string   `db:"suggestions" json:"suggestions"`
	CategoryManuallySet *bool      `db:"category_manually_set" json:"category_manually_set"`
	MerchantManuallySet *bool      `db:"merchant_manually_set" json:"merchant_manually_set"`
	Forgiven            *bool      `db:"forgiven" json:"forgiven"`
	ID                  int64      `db:"id" json:"id"`
	UserID              uuid.UUID  `db:"user_id" json:"user_id"`
}

func (q *Queries) UpdateTransaction(ctx context.Context, arg UpdateTransactionParams) error {
	_, err := q.db.Exec(ctx, updateTransaction,
		arg.ExternalID,
		arg.AccountID,
		arg.TxDate,
		arg.TxAmountCents,
		arg.TxCurrency,
		arg.TxDirection,
		arg.TxDesc,
		arg.ClearCategory,
		arg.CategoryID,
		arg.Merchant,
		arg.UserNotes,
		arg.ForeignAmountCents,
		arg.ForeignCurrency,
		arg.ExchangeRate,
		arg.Suggestions,
		arg.CategoryManuallySet,
		arg.MerchantManuallySet,
		arg.Forgiven,
		arg.ID,
		arg.UserID,
	)
	return err
}

